async def test_real_runner_on_trusted_test_fixture(tmp_path):
    # This file is a trusted system-test fixture, not generated by an LLM.
    project=tmp_path/'trusted';project.mkdir()
    (project/'test_fixture.py').write_text('import unittest\nclass TestFixture(unittest.TestCase):\n    def test_arithmetic(self):\n        self.assertEqual(2+2,4)\n',encoding='utf-8')
    result=await ApprovedHostRunner().run(project,lambda:False)
    assert result['passed'] and result['test_count']==1 and result['exit_code']==0
    assert result['isolated'] is False


async def test_runner_rejects_zero_tests(tmp_path):
    project=tmp_path/'empty';project.mkdir()
    result=await ApprovedHostRunner().run(project,lambda:False)
    assert not result['passed'] and result['test_count']==0


async def test_runner_cancellation(tmp_path):
    project=tmp_path/'trusted';project.mkdir()
    (project/'test_fixture.py').write_text('import time\ntime.sleep(60)\n',encoding='utf-8')
    started=time.monotonic()
    result=await ApprovedHostRunner().run(project,lambda:time.monotonic()-started>0.3)
    assert not result['passed'] and result['reason']=='cancelled'


async def test_restart_after_plan_side_effects_does_not_duplicate(system):
    service,worker,http,runner=system
    p=service.create_project('Crash');task=service.enqueue(p.id,'Build','crash-request')
    task_id,run_id=worker.claim()
    await worker.execute(task_id)  # Simulate crash before tick marks the parent complete.
    with service.sessions() as s: count=len(list(s.scalars(select(Task))))
    service.recover();service.action(task_id,'retry');await worker.tick()
    with service.sessions() as s:
        assert len(list(s.scalars(select(Task))))==count
        assert s.get(Task,task_id).status=='COMPLETED'
    assert worker.client.calls.count('ceo')==1


async def test_restart_after_repair_side_effects_does_not_duplicate(system):
    service,worker,http,runner=system
    p=service.create_project('Crash repair');service.enqueue(p.id,'Build','crash-repair-request')
    await worker.tick();await worker.tick()
    worker.client.review_failures=1
    task_id,run_id=worker.claim()
    await worker.execute(task_id)
    service.recover();service.action(task_id,'retry');await worker.tick()
    with service.sessions() as s:
        assert len(list(s.scalars(select(Task).where(Task.agent=='developer'))))==2


async def test_overwrite_requires_specific_approval(system):
    service,worker,http,runner=system
    p=service.create_project('Overwrite');service.enqueue(p.id,'Build','overwrite-request')
    ws=service.project_workspace(p.id);ws.write('main.py','# My own file')
    await worker.tick();await worker.tick()
    assert ws.read('main.py')=='# My own file'
    with service.sessions() as s:
        approval=s.scalar(select(Approval))
        assert approval.kind=='overwrite'
        assert 'My own file' in approval.details['diffs']['main.py']
    service.decision(approval.id,Decision(approve=True));await worker.tick()
    assert 'def add' in ws.read('main.py')


async def test_changed_source_during_execution_blocks_release(system):
    service,worker,http,runner=system
    p,task,approval=await prepare(system)
    original=runner.run
    async def mutate(directory,cancelled):
        result=await original(directory,cancelled)
        service.project_workspace(p.id).write('main.py','def add(a,b): return 99\n')
        return result
    runner.run=mutate
    service.decision(approval.id,Decision(approve=True,acknowledge_host_execution=True))
    await worker.tick();await worker.tick()
    with service.sessions() as s:
        assert s.scalar(select(Artifact)) is None
        # The stricter gate now stops at QA before the release can be claimed.
        assert s.scalar(select(Task).where(Task.agent=='release')).status=='PENDING'
        qa=s.get(Task,approval.task_id)
        assert qa.status=='FAILED' and qa.result['phase']=='post_tests'
        assert qa.result['tests']['passed'] is True
        assert qa.result['tested_hashes'] == approval.details['hashes']


async def test_results_survive_failed_qa_inference(system):
    service,worker,http,runner=system
    p,task,approval=await prepare(system)
    service.decision(approval.id,Decision(approve=True,acknowledge_host_execution=True))
    worker.client.error=RuntimeError('LLM offline after test execution')
    await worker.tick()
    with service.sessions() as s:
        qa=s.get(Task,approval.task_id)
        assert qa.result['phase']=='post_tests'
        assert qa.result['tests']['passed']
    worker.client.error=None
    service.action(approval.task_id,'retry');await worker.tick()
    assert runner.calls==1


async def test_full_pipeline_with_real_runner_and_trusted_fixture(system):
    service,worker,http,runner=system
    worker.runner=ApprovedHostRunner()
    p,task,approval=await prepare(system)
    service.decision(approval.id,Decision(approve=True,acknowledge_host_execution=True))
    await worker.tick();await worker.tick()
    with service.sessions() as s:
        artifact=s.scalar(select(Artifact))
        assert artifact is not None
        qa=s.get(Task,approval.task_id)
        assert qa.result['tests']['test_count']==1
        assert qa.result['tests']['passed'] is True
        assert 'OK' in qa.result['tests']['output']


def test_static_analysis_never_imports_code(system,tmp_path):
    service,worker,http,runner=system
    p=service.create_project('Static');task=service.enqueue(p.id,'Build','static-request')
    ws=service.project_workspace(p.id)
    marker=tmp_path/'SHOULD_NOT_EXIST'
    ws.write('main.py',f'from pathlib import Path\nPath({str(marker)!r}).write_text("executed")\n')
    with service.sessions.begin() as s:
        result=ToolRegistry(ws,s,task,{}).inspect()
    assert not marker.exists()
    assert result['kind']=='static_only'


def test_coding_context_excludes_stale_verdicts_and_contains_current_task(system):
    service,worker,http,runner=system
    p=service.create_project('Current evidence')
    service.enqueue(p.id,'Build console app','context-regression-request')
    ws=service.project_workspace(p.id)
    ws.write('main.py','tasks = []\n')
    with service.sessions.begin() as s:
        MemoryService(s).save(p.id,'STALE_VERDICT: all tests passed; tasks = {}')
        dev=Task(project_id=p.id,agent='developer',title='Repair',description='Fix current persistence',iteration=1)
        qa=Task(project_id=p.id,agent='qa',title='Review',description='Verify actual code')
        s.add_all([dev,qa]);s.flush()
    for task in [dev,qa]:
        context=worker.context(task,True)
        assert 'STALE_VERDICT' not in context
        assert 'tasks = []' in context
        import json
        assert json.loads(context)['CurrentTask']['description'] == task.description
        assert task.description in context
